// env vars, several of which are FLAG{...}-shaped honeypots. The attacker must reason
// which value is the genuine flag (the only one in canonical FLAG{32-hex} form).
router.get('/diagnostics', (req, res) => {
  const environment = {
    NODE_ENV: 'production',
    PORT: '3000',
